comms.text:
@1 אַתּוּן קָיְמִין יוֹמָא דֵין כֻּלְכוֹן קֳדָם יְיָ אֱלָהֲכוֹן רֵישֵׁיכוֹן שִׁבְטֵיכוֹן סָבֵיכוֹן וְסָרְכֵיכוֹן כָּל אֱנַשׁ יִשְׂרָאֵל:
@2 טַפְלְכוֹן נְשֵׁיכוֹן וְגִיוֹרָךְ דִי בְּגוֹ מַשְׁרִיתָךְ מִלָקֵטּ אָעָיךְ עַד מְלֵי מַיָיךְ:
@3 לְאָעָלוּתָךְ בִּקְיָמָא דַיְיָ אֱלָהָךְ וּבְמוֹמָתֵהּ דִי יְיָ אֱלָהָךְ גְזַר עִמָךְ יוֹמָא דֵין:
@4 בְּדִיל לַאֲקָמָא יָתָךְ יוֹמָא דֵין קֳדָמוֹהִי לְעַמָא וְהוּא יְהֵי לָךְ לֶאֶלָהּ כְּמָא דִי מַלִיל לָךְ וּכְמָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@5 וְלָא עִמְכוֹן בִּלְחוֹדֵיכוֹן אֲנָא גְזַר יָת קְיָמָא הָדָא וְיָת מוֹמָתָא הָדָא:
@6 אֲרֵי יָת מָן דְאִיתוֹהִי הָכָא עִמָנָא קָאֵם יוֹמָא דֵין קֳדָם יְיָ אֱלָהָנָא וְיָת מָן דְלֵיתוֹהִי הָכָא עִמָנָא יוֹמָא דֵין:
@7 אֲרֵי אַתּוּן יְדַעְתּוּן יָת דִיתֵבְנָא בְּאַרְעָא דְמִצְרָיִם וְיָת דִי עֲבַרְנָא בְּגוֹ עַמְמַיָא דִי עֲבַרְתּוּן:
@8 וַחֲזֵיתוּן יָת שִׁקוּצֵיהוֹן וְיָת טַעֲוָתְהוֹן אָעָא וְאַבְנָא כַּסְפָּא וְדַהֲבָא דִי עִמְהוֹן:
@9 דִילְמָא אִית בְּכוֹן גְבַר אוֹ אִתְּתָא אוֹ זַרְעִית אוֹ שִׁבְטָא דִי לִבֵּהּ פָּנֵי יוֹמָא דֵין מִדַחַלְתָּא דַייָ אֱלָהָנָא לִמְהַךְ לְמִפְלַח יָת טַעֲוַת עַמְמַיָא הָאִנוּן דִילְמָא אִית בְּכוֹן גְבַר מְהַרְהַר חֶטְאִין אוֹ זָדוֹן:
@10 וִיהֵי בְּמִשְׁמְעֵהּ יָת פִּתְגָמֵי מוֹמָתָא הָדָא וִיחַשַׁב בְּלִבֵּהּ לְמֵימַר שְׁלָמָא יְהֵי לִי אֲרֵי בְּהַרְהוֹר לִבִּי אֲנָא אָזֵל בְּדִיל לְאוֹסָפָא לֵהּ חֶטְאֵי שָׁלוּתָא עַל זְדָנוּתָא:
@11 לָא יֵיבֵי יְיָ לְמִשְׁבַּק לֵהּ אֲרֵי בְּכֵן יִתְקֵף רָגְזָא דַיְיָ וְחֶמְתֵהּ בְּגַבְרָא הַהוּא וְיִדְבְּקוּן בֵּהּ כָּל לְוָטַּיָא דִכְתִיבִין בְּסִפְרָא הָדֵין וְיִמְחֵי יְיָ יָת שְׁמֵהּ מִתְּחוֹת שְׁמַיָא:
@12 וְיַפְרְשִׁנֵהּ יְיָ לְבִישָׁא מִכֹּל שִׁבְטַיָא דְיִשְׂרָאֵל כְּכֹל לְוָטֵי קְיָמָא דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין:
@13 וְיֵימַר דָרָא בַתְרָאָה בְּנֵיכוֹן דִי יְקוּמוּן מִבַּתְרֵיכוֹן וּבַר עַמְמִין דִי יֵיתֵי מֵאַרְעָא רְחִיקָא וְיֶחֱזוּן יָת מְחָתָא דְאַרְעָא הַהִיא וְיָת מַרְעָהָא דִי אַמְרַע יְיָ בַּהּ:
@14 גָפְרֵתָא וּמִלְחָא יְקִידַת כָּל אַרְעַהּ לָא תִזְרַע וְלָא תַצְמַח וְלָא יִסַק בַּהּ כָּל עֶסְבָּא כְּמַהְפֶּכְתָּא דִסְדֹם וַעֲמֹרָה אַדְמָה וּצְבוֹיִם דִי הֲפַךְ יְיָ בְּרָגְזֵהּ וּבְחֶמְתֵהּ:
@15 וְיֵימְרוּן כָּל עַמְמַיָא עַל מֶה עֲבַד יְיָ כְּדֵין לְאַרְעָא הָדָא מָא תְקוֹף רָגְזָא רַבָּא הָדֵין:
@16 וְיֵימְרוּן עַל דִשְׁבָקוּ יָת קְיָמָא דַיְיָ אֱלָהָא דַאֲבָהָתְהוֹן דִי גְזַר עִמְהוֹן בְּאַפָּקוּתֵהּ יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם:
@17 וַאֲזָלוּ וּפְלָחוּ לְטַעֲוַת עַמְמַיָא וּסְגִידוּ לְהוֹן דַחֲלָן דִי לָא יְדָעֻנוּן וְלָא אוֹטִיבָא לְהוֹן:
@18 וּתְקֵף רָגְזָא דַיְיָ בְּאַרְעָא הַהִיא לְאַיְתָאָה עֲלַהּ יָת כָּל לְוָטַיָא דִכְתִיבִין בְּסִפְרָא הָדֵין:
@19 וְטַּלְטְּלִנוּן יְיָ מֵעַל אַרְעֲהוֹן בִּרְגַז וּבְחֵמְתָא וּבִתְקוֹף רְגַז וְאַגְלִנוּן לְאַרְעָא אָחֳרִי כְּיוֹמָא הָדֵין:
@20 דְמִטַמְרָן קֳדָם יְיָ אֱלָהָנָא וּדְמִגַלְיָן לָנָא וְלִבְנָנָא עַד עֳלָם לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@21 וִיהֵי אֲרֵי יֵיתוּן עֲלָךְ כָּל פִּתְגָמַיָא הָאִלֵין בִּרְכָן וּלְוָטִין דִי יְהָבִית קֳדָמָךְ וּתְתוּב לְלִבָּךְ בְּכָל עַמְמַיָא דִי אַגְלָךְ יְיָ אֱלָהָךְ לְתַמָן:
@22 וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ כְּכֹל דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין אַתְּ וּבְנָיךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@23 וִיתוּב יְיָ אֱלָהָךְ יָת שְׁבִי גַלְוָתָךְ וִירַחַם עֲלָךְ וִיתוּב וְיִכְנְשִׁנָךְ מִכָּל עַמְמַיָא דִי בַדְרָךְ יְיָ אֱלָהָךְ לְתַמָן:
@24 אִם יְהֵי גַלְוָתָךְ בִּסְיָפֵי שְׁמַיָא מִתַּמָן יִכְנְשִׁנָךְ יְיָ אֱלָהָךְ וּמִתַּמָן יְקָרְבִנָךְ:
@25 וְיָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִירִיתוּ אֲבָהָתָךְ וְתֵרְתַהּ וְיוֹטֶב לָךְ וְיַסְגִנָךְ מֵאֲבְהָתָךְ:
@26 וְיֶעְדֵי יְיָ אֱלָהָךְ יָת טַפְשׁוּת לִבָּךְ וְיָת טַּפְשׁוּת לִבָּא דִבְנָיךְ לְמִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ בְּדִיל חַיָיךְ:
@27 וְיִתֵּן יְיָ אֱלָהָךְ יָת כָּל לְוָטַיָא הָאִלֵין עַל בַּעֲלֵי דְבָבָךְ וְעַל סָנְאָךְ דִי רְדָפוּךְ:
@28 וְאַתְּ תְּתוּב וּתְקַבַּל לְמֵימְרָא דַיְיָ וְתַעְבֵּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@29 וְיוֹתְרִינָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ לְטָּבָא אֲרֵי יְתוּב יְיָ לְמֶחֱדֵי עֲלָךְ לְטָב כְּמָא דִי חֲדִי עַל אֲבָהָתָךְ:
@30 אֲרֵי תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין אֲרֵי תְתוּב קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@31 אֲרֵי תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לָא מַפְרְשָׁא הִיא מִנָךְ וְלָא רְחִיקָא הִיא:
@32 לָא בִשְׁמַיָא הִיא לְמֵימָר מָן יִסַק לָנָא לִשְׁמַיָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@33 וְלָא מֵעִבְרָא לְיַמָא הִיא לְמֵימַר מָן יֵעִבַר לָנָא לְעִבְרָא דְיַמָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@34 אֲרֵי קָרִיב לָךְ פִּתְגָמָא לַחֲדָא בְּפוּמָךְ וּבְלִבָּךְ לְמֶעְבְּדֵהּ:
@35 חֲזֵי דִיהָבִית קֳדָמָךְ יוֹמָא דֵין יָת חַיֵי וְיָת טַבְתָא וְיָת מוֹתָא וְיָת בִּישָׁא:
@36 דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי וְדִינוֹהִי וְתֵיחֵי וְתִסְגֵי וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@37 וְאִם יִפְנֵי לִבָּךְ וְלָא תְקַבֵּל וְתִטְּעֵי וְתִסְגוּד לְטַּעֲוַת עַמְמַיָא וְתִפְלְחִנוּן:
@38 חַוֵיתִי לְכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן לָא תוֹרְכוּן יוֹמִין עַל אַרְעָא דִי אַתְּ עָבֵר יָת יַרְדְנָא לְמֵעַל לְתַמָן לְמֵירְתַהּ:
@39 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא חַיֵי וּמוֹתָא יְהָבִית קֳדָמָךְ בִּרְכָן וּלְוָטִין וְתִתִּרְעֵי בְּחַיֵי בְּדִיל דְתֵיחֵי אַתְּ וּבְנָיךְ:
@40 לְמִרְחַם יָת יְיָ אֱלָהָךְ לְקַבָּלָא לְמֵימְרֵהּ וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ אֲרֵי הוּא חַיָיךְ וְאוֹרָכוּת יוֹמָיךְ לְמִתַּב עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לְהוֹן: פפפ:

@1 **אתם נצבים.** מלמד שכנסם משה לפני הקדוש ברוך הוא ביום מותו להכניסם בברית: **ראשיכם שבטיכם.** ראשיכם לשבטיכם: **זקניכם ושטריכם.** החשוב חשוב קודם, ואחר כך כל איש ישראל:
@2 **מחטב עציך.** מלמד שבאו כנענים להתגיר בימי משה, כדרך שבאו גבעונים בימי יהושע. וזהו האמור בגבעונים (יהושע ט, ד) ויעשו גם המה בערמה, ונתנם משה חוטבי עצים ושואבי מים:
@3 **לעברך.** להיותך עובר בברית. ולא יתכן לפרשו כמו להעבירך, אלא כמו (לעיל ד, יד) לעשותכם אותם: **לעברך בברית.** דרך העברה, כך היו כורתים ברית, עושין מחצה מכאן ומחצה מכאן ועוברים בנתים, כמו שנאמר (ירמיה לד, יח) העגל אשר כרתו לשנים ויעברו בין בתריו:
@4 **למען הקים אתך היום לו לעם.** כל כך הוא נכנס לטרוח למען קים אתך לפניו לעם: **והוא יהיה לך לאלהים.** לפי שדבר לך ונשבע לאבותיך שלא להחליף את זרעם באמה אחרת, לכך הוא אוסר אתכם בשבועות הללו, שלא תקניטוהו אחר שהוא אינו יכול להבדל מכם. עד כאן פרשתי לפי פשוטו של פרשה. ומדרש אגדה, למה נסמכה פרשת אתם נצבים לקללות, לפי ששמעו ישראל מאה קללות חסר שתים, חוץ ממ''ט שבתורת כהנים, הוריקו פניהם ואמרו מי יוכל לעמוד באלו, התחיל משה לפיסם אתם נצבים היום, הרבה הכעסתם למקום ולא עשה אתכם כליה והרי אתם קימים לפניו: **היום.** כיום הזה שהוא קים והוא מאפיל ומאיר, כך האיר לכם וכך עתיד להאיר לכם, והקללות והיסורין מקימין אתכם ומציבין אתכם לפניו. ואף הפרשה של מעלה מזו פיוסין הם (לעיל פסוק א') , אתם ראיתם את כל אשר עשה. דבר אחר, אתם נצבים. לפי שהיו ישראל יוצאין מפרנס לפרנס ממשה ליהושע, לפיכך עשה אותם מצבה כדי לזרזם. וכן עשה יהושע, וכן שמואל (שמואל א' יב, ז) התיצבו ואשפטה אתכם, כשיצאו מידו ונכנסו לידו של שאול:
@6 **ואת אשר איננו פה.** ואף עם דורות העתידים להיות:
@7 **כי אתם ידעתם** וגו' **ותראו את שקוציהם.** לפי שראיתם האמות עובדי עבודה זרה ושמא השיא לב אחד מכם אותו ללכת אחריהם, פן יש בכם וגו' (פסוק יז) לפיכך אני צריך להשביעכם:
@8 **ותראו את שקוציהם.** על שם שהם מאוסים כשקצים: **גלליהם.** שמסרחים ומאוסין כגלל: **עץ ואבן.** אותן של עצים ושל אבנים ראיתם בגלוי, לפי שאין הגוים יראים שמא יגנבו, אבל של כסף וזהב, עמהם, בחדרי משכיתם הם, לפי שהם יראים שמא יגנבו:
@9 **פן יש בכם.** שמא יש בכם: **אשר לבבו פנה היום.** מלקבל עליו הברית: **שרש פרה ראש ולענה.** שרש מגדל עשב מר כגידין, שהם מרים, כלומר מפרה ומרבה רשע בקרבכם:
@10 **והתברך בלבבו.** לשון ברכה, יחשב בלבו ברכת שלום לעצמו לאמר, לא יבואוני קללות הללו, אך שלום יהיה לי: **והתברך.** בינדיר''א שי''י בלע''ז [יברך את עצמו] , כמו והתגלח והתפלל: **בשררות לבי אלך.** במראית לבי, כמו (במדבר כד, יז) אשורנו ולא קרוב, כלומר מה שלבי רואה לעשות: **למען ספות הרוה.** לפי שאוסיף לו פרענות על מה שעשה עד הנה בשוגג והייתי מעביר עליהם, וגורם עתה שאצרפם עם המזיד ואפרע ממנו הכל. וכן תרגם אנקלוס בדיל לאוספא ליה חטאי שלותא על זדנותא, שאוסיף לו אני השגגות על הזדונות: **הרוה.** שוגג שהוא עושה כאדם שכור שלא מדעת: **הצמאה.** שהוא עושה מדעת ובתאוה:
@11 **יעשן אף ה'.** על ידי כעס הגוף מתחמם והעשן יוצא מן האף, וכן (ש''ב כב, ט) עלה עשן באפו, ואף על פי שאין זו לפני המקום, הכתוב משמיע את האזן כדרך שהיא רגילה ויכולה לשמוע, כפי דרך הארץ: **וקנאתו.** לשון חמה אנפרטמינ''ט [חמה] אחיזת לבישת נקמה, ואינו מעביר על המדה:
@12 **הכתובה בספר התורה הזה.** ולמעלה הוא אומר (לעיל כח, סא) בספר התורה הזאת גם כל חלי וכל מכה וגו' , הזאת, לשון נקבה, מוסב על התורה. הזה, לשון זכר, מוסב על הספר, ועל ידי פסוק הטעמים הן נחלקין לשתי לשונות, בפרשת הקללות הטפחא נתונה תחת בספר, והתורה הזאת דבוקים זה לזה, לכך אמר הזאת, וכאן הטפחה נתונה תחת התורה, נמצא ספר התורה דבוקים זה לזה, לפיכך לשון זכר נופל אחריו, שהלשון נופל על הספר:
@17 **לא ידעום.** לא ידעו בהם גבורת אלהות: **ולא חלק להם.** לא נתנם לחלקם. ואונקלוס תרגם ולא אוטיבא להון, לא הטיבו להם שום טובה, ולשון לא חלק אותו אלוה שבחרו להם, לא חלק להם שום נחלה ושום חלק:
@19 **ויתשם ה'.** כתרגומו וטלטלנון, וכן (ירמיה יב, יד) הנני נותשם מעל אדמתם:
@20 **הנסתרת לה' אלהינו.** ואם תאמרו מה בידינו לעשות, אתה מעניש את הרבים על הרהורי היחיד, שנאמר (פסוק יז) פן יש בכם איש וגו' , ואחר כך (פסוק כא) וראו את מכות הארץ ההיא, והלא אין אדם יודע טמונותיו של חברו, אין אני מעניש אתכם על הנסתרות, שהן לה' אלהינו והוא יפרע מאותו יחיד, אבל הנגלות' לנו ולבנינו לבער הרע מקרבנו, ואם לא נעשה דין בהם יענשו הרבים. נקוד על לנו ולבנינו, לדרוש, שאף על הנגלות לא ענש את הרבים עד שעברו את הירדן, משקבלו עליהם את השבועה בהר גרזים ובהר עיבל, ונעשו ערבים זה לזה:
@23 **ושב ה' אלהיך את שבותך.** היה לו לכתוב והשיב את שבותך, רבותינו למדו מכאן שהשכינה כביכול שרויה עם ישראל בצרת גלותם, וכשנגאלין הכתיב גאלה לעצמו, שהוא ישוב עמהם. ועוד יש לומר, שגדול יום קבוץ גליות ובקשי, כאלו הוא עצמו צריך להיות אוחז בידיו ממש איש איש ממקומו, כענין שנאמר (ישעיה כז, יב) ואתם תלקטו לאחד אחד בני ישראל, ואף בגליות שאר האמות מצינו כן (ירמיהו מח, מז) ושבתי שבות מואב:
@31 **לא נפלאת היא ממך.** לא מכסה היא ממך, כמו שנאמר (דברים יז, ח) כי יפלא, ארי יתכסי, (איכה א, ט) ותרד פלאים, (איוב מ, יג) ותרד במטמוניות. מכסה, חבוש בטמון:
@32 **לא בשמים היא.** שאלו היתה בשמים, היית צריך לעלות אחריה וללמדה:
@34 **כי קרוב אליך.** התורה נתנה לכם בכתב ובעל פה:
@35 **את החיים ואת הטוב.** זה תלוי בזה, אם תעשה טוב הרי לך חיים, ואם תעשה רע הרי לך המות. והכתוב מפרש והולך היאך:
@36 **אשר אנכי מצוך היום לאהבה.** הרי הטוב, ובו תלוי: **וחיית ורבית.** הרי החיים:
@37 **ואם יפנה לבבך.** הרי הרע:
@38 **כי אבד תאבדון.** הרי המות:
@39 **העדתי בכם היום את השמים ואת הארץ.** שהם קימים לעולם וכאשר תקרה אתכם הרעה יהיו עדים שאני התריתי בכם בכל זאת. דבר אחר, העידתי בכם היום את השמים וגו' , אמר להם הקדוש ברוך הוא לישראל, הסתכלו בשמים שבראתי לשמש אתכם, שמא שנו את מדתם, שמא לא עלה גלגל חמה מן המזרח והאיר לכל העולם, כענין שנאמר (קהלת א, ה) וזרח השמש ובא השמש, הסתכלו בארץ שבראתי לשמש אתכם, שמא שנתה מדתה, שמא זרעתם אותה ולא צמחה, או שמא זרעתם חטים והעלתה שעורים, ומה אלו שנעשו לא לשכר ולא להפסד אם זוכין אין מקבלין שכר ואם חוטאין אין מקבלין פרענות, לא שנו את מדתם, אתם, שאם זכיתם תקבלו שכר, ואם חטאתם תקבלו פרענות על אחת כמה וכמה: **ובחרת בחיים.** אני מורה לכם שתבחרו בחלק החיים, כאדם האומר לחברו בחר לך חלק יפה בנחלתי, ומעמידו על חלק היפה ואומר לו, את זה ברור לך, ועל זה נאמר (תהלים טז, ה) ה' מנת חלקי וכוסי אתה תומיך גורלי, הנחת ידי על גורל הטוב לומר את זה קח לך:
@41 **כחתן.** אשר ילבש לבושי פאר ככהן גדול: **וככלה תעדה כליה.** תכשיטיה:
@42 **כי כארץ תוציא צמחה וגו':**
@43 **למען ציון.** אעשה ולא אחשה על מה שעשו לה: **לא אשקוט.** לא יהא שלום לפני עד יצא כנוגה צדקה:
@44 **יקבנו.** יפרשנו:
@46 **בעולה.** מיושבת:
@47 **כי יבעל וגו'.** ארי כמה דמתיתב עולם עם בתולתא כן יתייתבין בגוייכי בנייכי:
@48 **על חומותיך ירושלים.** רבותינו דרשוהו כמשמעו מלאכי' המזכירים את ה' על חורבנה לבנותה מאי אמרי אתה תקום תרחם ציון ( תהלים קב ) כי בחר ה' בציון ( שם קלב ) כדאיתא במסכת מנחות וי"ת חומותיך אבות הראשונים המגינים עלינו כחומה: **הפקדתי שומרים.** לכתוב ספר זכרונות שלא ישתכח זכותם מלפני: **לא יחשו.** מלהזכיר זכותם לפני: **המזכירים את ה'.** את זכות האבות: **אל דמי לכם.** אל תחרישו:
@51 **יאכלוהו.** מוסב על דגנך:
@52 **ישתוהו.** מוסב על תירושך: **עברו עברו בשערים.** אמר נבייא עברו ותובו בתרעיא אפנו לבא דעמא לאורח תקנא: **סלו סלו המסלה.** כבשו הדרך בטי"ץ לוקמי"ן בלע"ז סולו לשון מסלה הוא: **סקלו מאבן.** סקלו המסילה והשליכו אבני מכשול לצדדין, סקלו אישפירייא"ן בלע"ז. מאבן. מהיות שם אבן וכנגד יצר הרע הוא אומר, ויש עוד לפותרו על תיקון הדרכים לקבוץ הגליות: **הרימו נס.** כלונס פורקא בלע"ז אות הוא שיקבצו אלי ויביאו לי את הגולים אצלם:
@53 **הנה שכרו.** שמוכן לתת לעבדיו מוכן אתו: **ופעולתו.** שכר הפעולה שפעלו עמו לפניו הוא מוכן לתת:
@55 **מי זה בא מאדום.** נתנבא הנביא על שעיר ובצרה, אמרו רבותינו שתי טעיות עתיד שר של שעיר לטעות כסבור הוא שבצרה היא בצר במדבר שהיתה עיר מקלט, וטועה משום שאין קולטת אלא שוגג והוא הרג את ישראל מזיד, ועוד יש מדרש אגדה על שהספיקה בצרה מלך לשעיר במות מלכה הראשון וימלך תחתיו יובב בן זרח מבצרה ובצרה ממואב היא כענין שנא' על קריות ועל בצרה: **זה.** ( שהיה ) הדור בלבושו וצעה ונאזר ברוב כחו והקב"ה משיבו אני הוא שעלתה לפני לדבר בצדקת האבות ובצדקת דורו של צרה וצדקתי גם היא עמהם ונגליתי להיות רב להושיע והם אומרים מדוע אדום ללבושך מדוע בגדיך אדומים:
@57 **ומעמים אין איש אתי.** מתייצב לפני להלחם: **ויז נצחם.** דמם שהוא תוקפו ונצחונו של אדם: **אגאלתי.** כמו נגאלו בדם ( איכה ד ):
@59 **ואביט ואין עוזר.** לישראל: **ואשתומם.** ל' שתיקה וכבר פירשתי למעלה וישתומם כי אין מפגיע: **וחמתי היא סמכתני.** חמתי שיש לי על האומות אשר אני קצפתי מעט על עמי והמה עזרו לרעה היא סמכתני חיזקה ידי ועוררה את לבי ליפרע מהם ואע"פ שאין ישראל ראוין והגונים לגאולה:
@60 **ואבוס.** ל' מתגולל בדם ודורך ברגלים כמו מתבוססת בדמיך ( יחזקאל טז ) וכמו בוססו את חלקתי ( ירמיה יב ): **נצחם.** גבורת נצחונם:
@61 **חסדי ה' אזכיר.** הנביא אמר אזכיר את ישראל את חסדי ה': **ורב טוב.** אזכיר אשר גמל לבית ישראל ברחמיו:
@62 **אך עמי המה.** אע"פ שגלוי לפני שיבגדו בי מכל מקום עמי הם והרי הם לפני כבנים אשר לא ישקרו:
@63 **בכל צרתם.** שהביא עליהם. לא צר. לא היצר להם כפי מעלליהם שהיו ראויין ללקות כי מלאך פניו הוא מיכאל שר הפנים ממשמשי' לפניו הושיעם תמיד בשליחותו של מקום:

@1 **ראשיכם שבטיכם.** רוצה לומר ראשיכם ראשי שבטיכם:
@1 **זקניכם.** הם השופטים וקראם זקנים מצד חכמתם ולזה אמר זקני העיר ההיא כמו שקדם על השופטים. והנה זכרם לפי מדרגתם וזה שכבר זכר תחלה ראשי השבטי ואחר כך השופטים ואחר כך השוטרים. ואחר כך זכר כל איש ישראל ואחר כך זכר הטף כי הם כשיגדלו יגיעו לגדר המצות ואחר כך זכר הנשים ואחר כך זכר הגרים אשר בקרב המחנה והם הגרים והתושבים אמר מחוטב עציך על שואב מימיך והם שכיריהם שהיו עושים מלאכתם והנה אמר זה כי כלם היו שם לשמוע דבריו כי דבריו היו לכל ישר כמו שנזכר בראש זה הספר האחרון:
@3 **לעברך בברית ה' אלהיך ובאלתו וגו'.** הנה היה דרך כורתי הברית שיכרתו דבר לחציין ויעברו אחר כך בין הבתרים כמו שראינו בברית בין הבתרים ולזאת הסבה התחכמה התורה בכריתת הברית שתהיה הברכה כנגד הר גריזים והקללה כנגד הר עיבל והיתה התורה כתובה שם בהר עיבל באבני המזבח והקריבו שם קרבנות להעיר שבעבדם השם יתעלה ובשמרם דרכי התורה ימלטו מהקללות ההם והנה היו עוברים ישראל אחר זה עם כל הנטפלין להם בין שני ההרים ההם כדי שיעברו בין ברית השם יתעלה לישראל ובין אלתו להורות שהם כרתו ברית עם השם יתעלה לקיים תורתו בזה האופן שאם יקיימום יחולו עליהם הברכות שיעד השם יתע' ואם לא יקימום יחולו עליהם הקללות אשר קבלום עליהם ויעדם להם השם יתעלה גם כן ואמר כי בזה הברית שהש' יתעלה כורת לישראל היום יקים לו לעם מיוחד מבין שאר העמים לא יובדל עם לעבודתו זולתו והוא יהיה לו לאלהי' לבדו ולמנהיגו למשגיח וכאלו אמר שאם לא יהיה לו לעם בשיתיחד לעבודתו גם השם יתעלה לא יהיה לו לאלהים כי זה תלוי בזה:
@5 **ולא אתכם לבדכם אנכי כורת.** אמ' זה בעבור הדורות הבאים ובעבור הגרי' שיתגיירו משאר האומות כי הם כלם נכנסים בזה הברית והנה האבות כרתו הברית הזה עליהם ועל זרעם והנכרי המתגייר יקבלהו עליו בעת היותו מתגייר:
@7 **כי אתם ידעתם את אשר ישבנו בארץ מצרים.** רוצה לומר הנה אתם ידעתם את אשר ישבנו בארץ מצרים ואת אשר עברנו בקרב הגוים אשר עברתם והם סיחון ועוג וחמשת מלכי מדין והכנעני מלך ערד וראיתם את שקוציה' ואת גלוליהם שעשו הם לאלהים מעץ ואבן אשר אין רוח בקרבם וכסף וזהב אשר שמו עם הצלמים ההם לנוי לפתות האנשים אליהם מצד הקשוט והיופי אשר בהם:
@9 **פן יש בכם איש או אשה או משפחה או שבט.** לפי שזה הדבר מגונה התחיל בפחות ואמר והוא היחיד או היחידה ואחר זה זכר המשפחה שהיא כוללת אנשים רבים ואחר זה זכר השבט שהוא כולל משפחות רבות ואמר פן יש בכם איש או אשה או משפחה או שבט אשר לבבו פונה היום מעם הש' יתעלה ללכת אחרי אלהי הגוים שזכרנו שעברנו בהם שמא יש בכם שרש פורה ממנו דבר מר מאד כמו ראש ולענה.
@10 **והיה בשמעו את דברי** הקללות האלה אשר עליהם וכרת הברית מהש"י את בני ישראל יחשוב בלבו הנה אני יהיה נקי מהקללות האלה ויהיה לי שלום ואתברך באשר אמשך למה שתביאני אליו בחירתי ושלא אשתדל לעיין בדברי התורה אי זה דבר ראוי לי לעשות ואי זה דבר ראוי שאמנע ממנו כדי שתהיה נוספת הרוה עם הצמאה והנה קרא התורה צמאה כי בעלי התאו הישארו צמאי' מאד ממה וקרא בזה ההולך בדרכי לבו כי בו תרוה נפשו ממה שהוא מתאוה אליו ולא תצמא או ירצה מאמרו שלום יהיה לי כי בשרירות לבי אלך שיוסיף על דברי התורה במחשבתו ההולך בדרי לבו ויאמר בברכות שאם ילך בדרכי לבו יהיה ברוך כשלא יכון לעבור על דברי התורה:
@11 **כי אז יעשן אף יי' וקנאתו באיש ההוא.** אמר זה כי בזה התנאי שחשב בלבו לא ימלט משיגיעו לו אלו הקללות ואם היה חוטא בזה האופן יחיד או יחידים ימחה הש"י את שמם מתחת השמי' ולא ישאר להם שום זכר ואם היה חוטא בזה האופן שבט או שבטים הנה יבדילו הש"י לרעה מכל שבטי ישראל ככל אלות הכתוב בספר התורה הזה ולהורות על הפלגת תחלואי השבט ההיא ומכותיה ובא הקללה בארצם וגלותם מעל אדמתם אמר שהדור אחרון שיהיה מהם וגם הנכרי שיבא מארץ רחוקה בראותם את מכות הארץ ההיא ותחלואיה יצדיקו הדין ויאמרו שכל זה הרע בא עליהם על עברם בברית הש"י ובאלתו ועבדו אלהים אחרים אשר לא ידעום אבותיהם ולא חלק להם הש"י שררה והנהג' על ישר' ואם חלק הש"י אותם לכל העמים שהם תחת ממשלתם ר"ל השמים והירח והכוכבים וצבא השמים ועל זה נתשם הש"י מעל אדמתם והשליכם אל ארץ אחרת כמו שהם היום הזה חוץ לארצם בארץ אחרת וזה ממה שיורה שהאיש שיסכים הש' יתעלה לכלותו לא השבט או השבטים ונדמה שזה כלו הוא על ירבעם ועשרת השבטים. והנה ירבעם היה האיש אשר היתה עצתו כך לפרוק מעליו עול תורה ולזה עשה לו שני עגלי זהב והנה בא ענשו שנמחה שמו מתחת השמים עד שלא נשאר לירבעם משתין בקיר וכן היה בשאר מלכי ישראל שאחזו דרכו ואמנם עשרת השבטים הגלה אותם ממלך אשור מעל אדמתם וקודם זה נהרגו מהם רבים מאד ומתו ברעב עד שלא נשארו מהם כי אם מתי מעט וגלה אותם מלך אשור לחלח וחבור נהר גוזן וערי מדי:
@20 **הנסתרות לה' אלהינו והנגלות לנו וגו'.** אמר זה כי אולי יחשוב חושב כי האדם יחטא אם לא יושגו לו כונות התורה ואם היה שהישירה אליו מקניין השלמות האנושי ואם היה כן היה בלתי אפשר שיהיה אדם צדיק בארץ שלא יחטא כי לא יוכל לעמוד על כונות התורה בשלמות ואם היה זה כן איך יתכן שיצוה השם יתעלה לשמור כל מצותיו ואם לא ישמרו כלם יגיע להם אלו העונשים הנפלאים והנה להסיר זה הספק אמרה תורה כי הנסתרות שבמצות התורה והם הפעולות אשר תכוין אליהם בהם מפני היותם על מה שהם עליו הם דברים לא יושגו על תכליתם כי אם לשם יתעלה לבדו ולזה לא ייוחס חטא לבלתי עומד על כונותיה ואולם הנגלות ממותיה והם הפעולות והדברים שצותה התורה לעשות או להמנע מהם הם חוב' לנו ולבנינו תמיד לדורותינו לעשו' כפי מה שגזרה התורה מהם. ומזה יתבאר שאין ראוי לאדם שיאמר הנה מפני שכונת התורה במצות כך להישיר אל דבר כך או להרחיק מדבר כך הנה אני שאני מתיישר באופן שלם אל הכונה ההיא אין חשש אם אעבור על זאת המצוה ולזה אמר הנסתרות להשם אלהינו להורות כי אין יכולת באדם לעמוד על כונות התורה בשלמות הלא הראה כי גם במצות שביארה התורה תועלותם חטא שלמה המלך בחשבו שהוא ישמר ממה שכונה התורה במצוה ההיא להרחיקו כי הוא הרבה לו נשים לחושבו שלא יטו לבבו רוב חכמתו וגודל מעלתו ונכשל בזה ובכלל הנה גם כן מה שזכרה התורה תועלת מצוה הוא אפשר שיהיה בה אצל הש' יתעלה תועלת אחר הלא תראה כי התורה זכרה במקום אחד במצות שבת תועלת אחת והוא שזכר לחדוש הש' יתעלה העלם ובמקום אחר זכרה בו תועלת אחר והוא שהוא זכר יציאת מצרים ולזה הוא מבואר שאין ראיה ממה שנזכר מהתועלת במצוה שלא יהיה שם תועלת אחר זולתו אצל השם יתעלה כ"ש במה שנזכר בתורה התועלת אבל עמדנו עליו על דרך החקירה והעיון והבן זה השרש כי הוא מגדולי השרשים התוריים לשמור חכמת התורה שלא יבאו שועלים ויפרצוה:
@21 **והיה כי יבאו עליך כל הדברים האלה.** הגיד בזה שאחר שיבאו כל אלה הדברים הברכה תחלה ואחר כך הקללה כי כן היתה שהברכה היתה בימי יהושע ובימי הזקנים האריכו ימים אחריו שלא נפל דבר מכל הטוב כמו שנזכר בספר יהושע וכן היתה להם הברכה בימי קצת השופטים ובימי שמואל ושאול ודוד ושלמה שבימי קצת שאר מלכי' אחרים ובית שני בימי החשמונים הנה כל אלו הקללות הדברים מהקללות שזכרנו ותשוב אחר זה אל לבבך בכל המקומות שאתה גולה בהם לשוב עד יי' אלהיך ולשמוע בקולו בכל המצוה אשר אנכי מצוך היום בכל לבבך ובכל נפשך שכל תוקתך וציוריך יהיו לעבוד הש' יתע' ותישיר לזה גם כן בניך כדי לחנכם בעבוד' השם יתעלה לידה ומבטן הנה ישיב את שבותך וירחם אותך. וזה ידמה שיהיה בבנין בית שני ולזה אמר אחר זה ושב וקבצך מכל העמים. רוצה לומר שישוב שנית לקבצך מכל העמים וזה הוא אחר חרבן בית שני כי בבית שני נתקבצו בזה האופן וגם אמר הנביא יוסיף השם שנית ידו לקנות את שאר עמו והפליג בזה ואמר שגם אם יהיה הנדח לגלות בגוים בקצה הישוב משם יקבצהו השם יתעלה ויקחהו משם ויביאהו אל הארץ אשר ירשו אבותינו וזה הוא אמרו אחד מעיר ושנים ממשפחה רוצה לומר כי אע"פ שלא יהיה כי אם אחד בעיר משם יקחהו השם יתעלה וישמרהו שלא ימיתוהו הגוים אשר הוא בקרבם:
@25 **והטיבך והרבך מאבותיך.** רוצה לומר שאחר ייטיב להם השם יתעלה וירבה אותם רבוי נוסף על רבוי אבותיהם:
@26 **ומל ה' אלהיך את לבבך ואת לבב זרעך.** זה יורה שהשם יתעלה יעזרם אז וימול את ערלת לבבם שתכסה ממנו השגת השם יתעלה וזה יהיה מצד המופתים הנפלאים שיראה אותם אז כאמרו כימי צאתך מארץ מצרים אראנו נפלאות וכבר רמזו הנביאים במקומו' אל המופתים שיחודשו בעת ההיא ומכללם הוא תחיית המתים ואז יהפוך הש' יתע' אל עמים שפה ברורה לקרא כלם בשם יי' ולעבדו שכם אחד והנה בזה יתיישרו כלם לאהבה את השם יתע' בכל לבבם ובכל נפשם למען חייהם רוצה לומר למען החיים האמתיים ישיגום באהבתם אותו בכל תשוקותיהם ובכל ציוריהם ואז יתן הש' יתע' את כל הקללות האלה על האויבים ועל השונאים שרדפו ישראל בגלות ובכלל הנה אתה כשתשוב אל השם יתעלה ושמעת בקולו לעשות כל מצותיו מבלי גרעון אז תבא הברכה לך בבני' ובקניני' כאשר באה לאבותיך והנה ביאר בכל זה תכלית הביאור כי כשיתקיימו המצות שהוא נותן היום והם הכתובות בספר התורה הזאת יהיה להם כן וזאת ראיה זאתה התורה לא תומר ולא תשתנה לעולם וזו פנה גדולה מפנות התורה:
@31 **כי המצוה אשר אנכי מצוך היום.** אמר שהמצוה הזאת אינה בשמים שיצטרכו לביאור בה על יד הנביא כי מה שראוי להיות בה נכלל מזאת התורה ואינו גם כן מאופן מהעומק שיצטרכו לשופט:
@33 **מעבר הים.** להבין דבריה כי המצוה מעניינה והיא עשית המצוה הוא דבר קל מאד להגיד אותו בפה ולצייר אותו בלבבו וזה כי לא צותה התור' להעמיק העיון בה עד שיעמדו על כונותיה לפי מה שאפשר אך בטחה כי זה יתכן שישלם עם מה שהישירה אליו בזה הענין הבדל הכהנים והלוים לעבודת השם יתעלה כמו שביארנו במה שקדם:
@35 **ראה נתתי לפניך היום את החיים ואת הטוב ואת המות ואת הרע.** הנה החיים הם חיים הנפש כי הם החיי' האמתיים והטוב הם ההצלחות הגופייות כי הם גם כן ימשכו מקייום התורה כמו שקדם אבל התכלית העצמי לזה הוא החיים ואלו הטובות ג"כ הנמשכות מקיום מצות התורה הם מישירות אל השגת החיים ההם כי מי שהוא חסר להם ושלמה לא יתכן לו התבודדות בעיון באופן שלם והם המות והרע הם הפך שני אלו והם ימשכו מעזיבת התורה כי הוא יביא לעבוד עבודה זרה כמו שזכר:
@39 **העידותי בכם היום את השמים ואת הארץ.** נתן אותם לעדים כי הם קיימים להעיד שתמיד יתקיימו אלו הדברים עם שהם כמו עוזרים להמשיך זה כאלו יאמר שהשמים והארץ כלם יעזרו להגיע כל אלו הדברים מהברכות והקללות על דרך הכוכבים ממסילות' נלחמו עם סיסרא:
@39 **החיים והמות נתתי לפניך.** הזכיר לזכור תחילה החיים והמות האמתיים כי הם הגמול והעונש אנושיים ואחר זכר הברכה והקללה שהם הטוב והרע להיותם בלתי מכוונים בעצמות ואע"פ שכבר ימשכו מקיים מצוו' התור' והנטייה מהם. ולזה אמר ובחרת בחיים ולא אמר ובחרת בברכה כי אין ראוי לעבוד השם יתעלה כדי שיגיעו אלו הטובות הגופיות אך יעבדהו כדי שישיג החיים הערבים ההם כמו שאמר דוד תודיעיני אורח חיים שובע שמחות את פניך נעימות בימינך נצח ולזה אמר דוד במצוותיו חפץ מאד ולא בשכר מצותיו הנמשך באלו הטובות והקנינים הגופיים:
@40 **לאהבה את יי' אלהיך לשמוע בקולו ולדבקה בו כי היא חייך.** אמ' כי זה הוא בעצמותו חיי האד' והוא מבואר במה שאין ספק בו כי השגת השי"ת אשר בה תשלם אהבת האדם אותו לשמוע בקולו ובה ישלם לו הדבקות בו הוא החיים הנצחיים אשר לא יבלו ואמר אחר זה ואורך ימים לשבת על האדמה כי זה הטוב ימשך ממנה גם כן עם שהו' מישיר אל שיושגו החיים ההם באופן יותר שלם מפני היות הארץ מוכנת אל שידבק בה לאדם השפע האלהי כמו שזכרנו פעמים רבות:
